    {
      "id": "R7.3.0(6)",
      "title": "voltage out-of-range warning",
      "text": "The PCA pump shall detect power supply voltage out-of-range, issue a voltage out-of-range warning, and switch to battery backup when out-of-range."
    },
    {
      "id": "R7.3.0(7)",
      "title": "leakage current",
      "text": "The PCA pump must not leak current greater than 10 mA."
    },
    {
      "id": "R7.3.0(8)",
      "title": "component failure",
      "text": "Component failure must not harm patient (beyond stopping function)."
    },
    {
      "id": "R7.3.0(9)",
      "title": "electromagnetically compatible",
      "text": "The PCA pump must be electromagnetically compatible according to IEC 60601-1-2 (2001) Medical Electrical Equipment, Part 1: General Requirements for Safety, 2. Collateral Standard: Electromagnetic Compatibility - Requirements and Tests . (IEC 60601-1-2 2.3.1)"
    },
    {
      "id": "R7.3.0(10)",
      "title": "electrostatic discharge",
      "text": "The PCA pump must withstand electrostatic discharge."
    },
    {
      "id": "R7.3.0(11)",
      "title": "ﬁlter power interference",
      "text": "The PCA pump must ﬁlter power interference from mains."
    },
    {
      "id": "R7.4.0(1)",
      "title": "power-on self-test",
      "text": "The PCA pump shall perform a power-on self-test (POST) to assure system integrity after being turned on, yet before any infusion begins. Failure of POST shall raise a POST alarm , stop pump, record it in the Fault Log, and display the reason for failure on the user interface. (EC4 §4.2.4)"
    },
    {
      "id": "R7.4.0(2)",
      "title": "periodic self-tests",
      "text": "The PCA pump shall perform periodic self-tests to assure system integrity during long periods of use. Failure of a self-test shall raise a self-test alarm , stop pump, record it in the Fault Log, and display the reason for failure on the user interface. (EC22c §4.2.22)"
    },
    {
      "id": "R7.4.0(3)",
      "title": "continuous fault-detection",
      "text": "The PCA pump shall have continuous fault-detection and masking. Hardware monitors of thread heartbeat, memory error correction codes are examples. (EC22d §4.2.22)"
    },
    {
      "id": "R7.4.0(4)",
      "title": "single-event upsets",
      "text": "Occurrence of unavoidable single-event upsets caused by cosmic-ray-induced high- and thermal-energy neutrons must be either masked, or detected to fail-stop. (EC22d §4.2.22)"
    },
    {
      "id": "R7.4.0(5)",
      "title": "masked faults",
      "text": "Successfully masked faults shall be recorded in the Fault Log, but not raise an alarm. (EC22e §4.2.22)"
    },
    {
      "id": "R7.4.0(6)",
      "title": "hardware detected faults",
      "text": "All unmasked hardware detected faults shall raise a fault alarm, stop pump, record it in the Fault Log, and display the reason for fault on the user interface. (EC22 §4.2.22)"
    },
    {
      "id": "R7.4.0(7)",
      "title": "hardware fault indicator",
      "text": "Hardware faults that prevent operation of the Control Panel shall illuminate a hardware fault indicator (light-emitting diode). (EC22f §4.2.22)"
    },
    {
      "id": "R7.5.0(1)",
      "title": "tamper-resistant door",
      "text": "Because the drugs used for analgesia are often narcotic, requiring Drug Enforcement Agency (DEA) tracking if used in the United States, the drug reservoir and means to change prescriptions during infusion must be inhibited with a locked, tamper-resistant door."
    },
    {
      "id": "R7.5.0(2)",
      "title": "door closed and locked",
      "text": "Before infusion, the door must be closed and locked. (UC1.10 §4.1.1)"
    },
    {
      "id": "R7.5.0(3)",
      "title": "door key",
      "text": "Hospital procedures must endow the attending clinician access to the door key, yet prevent other persons’ access."
    },
    {
      "id": "R7.5.0(4)",
      "title": "pump case",
      "text": "The PCA pump case must be at least diﬃcult to breech as its tamper-resistant door. Breaking the case shall not be easier to access the drug reservoir than breeching the door."
    },
    {
      "id": "R7.6.0(1)",
      "title": "biocompatible",
      "text": "All materials that contact ﬂuid shall be biocompatible."
    },
    {
      "id": "R7.6.0(2)",
      "title": "cleaned and disinfected",
      "text": "The PCA pump shall be cleaned and disinfected after use."
    },
    {
      "id": "R7.7.0(1)",
      "title": "minimize drug leakage",
      "text": "The PCA pump shall minimize drug leakage."
    },
    {
      "id": "156",
      "title": "Clinician authentication",
      "text": "Clinicians authorization to operate the PCA pump must be authenticated. (UC1.4 §4.1.1)"
    },
    {
